def decide(observation, tools):
    scores = tools.match()
    frame = int(scores[1] > scores[0])
    if frame == 0:
        return 0, "left", {"heading": observation["views"][0]["heading"]}
    point = tools.point()
    if point[1] is not None:
        frac = point[1][1]
        if frac > 0.5:
            return 1, "right", {"heading": observation["views"][1]["heading"]}
        else:
            return 1, "left", {"heading": observation["views"][1]["heading"]}
    return frame, "right" if observation["views"][frame]["heading"] > 0 else "left", {"heading": observation["views"][frame]["heading"]}

